theorem graph_haar_restricted_mem {p : FullL2 2 × (SpinIndex → FullL2 2)}
    (hp : p ∈ M.fullClosedGraph) :
    graph_haar M G p ∈ originalRestrictedClosedGraph M G

def individualCoreSubmodule {N : ℕ} (M : AlgebraData N)
    (G : M.GaugeData) (a : SpinIndex) :
    Submodule ℂ (FullL2 N × FullL2 N)

def individualClosedSubmodule {N : ℕ} (M : AlgebraData N)
    (G : M.GaugeData) (a : SpinIndex) :
    Submodule ℂ (FullL2 N × FullL2 N)

def individualPhysicalGraph {N : ℕ} (M : AlgebraData N)
    (G : M.GaugeData) (a : SpinIndex) :
    Submodule ℂ (G.physicalSpace × G.physicalSpace)

def individualPhysicalOperator {N : ℕ} (M : AlgebraData N)
    (G : M.GaugeData) (a : SpinIndex) :
    G.physicalSpace →ₗ.[ℂ] G.physicalSpace

private theorem nativeCoreGraph_le {N : ℕ} (M : AlgebraData N)
    (G : M.GaugeData) (a : SpinIndex) :
    nativeCoreGraph M G a ≤ individualPhysicalGraph M G a

def pairedIndividualInput (a : SpinIndex)
    (u : (originalMinimalPhysicalHilbertChargeColumn pairedAlgebraData pairedGaugeData).domain) :
    (individualPhysicalOperator pairedAlgebraData pairedGaugeData a).domain
